const b = $input.first().json.body || {};
const rawFrom = b.From || "";
const cleanPhone = rawFrom.replace("whatsapp:", "").trim();
return [{ json: { rawFrom: rawFrom, cleanPhone: cleanPhone, messageText: b.Body || "", profileName: b.ProfileName || "", messageSid: b.MessageSid || "" } }];

const items = $input.all();
const ordered = items.slice().reverse();
const lines = ordered.map(function(i) {
  const f = i.json;
  const role = f.direction === "Outbound" ? "Assistant" : "Customer";
  return role + ": " + (f.body || "");
});
const history = lines.join("\n");
const currentMessage = $("Normalize Incoming Message").first().json.messageText;
const customerName = $("Normalize Incoming Message").first().json.profileName;
const customerNotes = $("Upsert Customer").first().json.notes || "";
const notesBlock = customerNotes ? ("Known customer profile (from previous conversations): " + customerNotes + "\n\n") : "";
const promptText = notesBlock + "Conversation history:\n" + history + "\n\nCustomer (" + customerName + ") new message: " + currentMessage;
return [{ json: { promptText: promptText } }];

