const latest = $input.first().json;
const savedId = $('Save Inbound Message').item.json.id;
const isLatest = latest && latest.id === savedId;
return [{ json: { isLatest: isLatest } }];

const raw = $input.first().json;
const text = raw.text || raw.content || '';
const originalBody = $('WhatsApp Inbound').item.json.body;
const newBody = Object.assign({}, originalBody, { Body: '[رسالة صوتية]: ' + text });
return [{ json: { body: newBody } }];

const raw = $input.first().json;
const text = raw.content || raw.text || raw.data || JSON.stringify(raw);
let parsed = { is_travel_document: false, description: 'صورة ارسلها العميل' };
try {
  const match = String(text).match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch (e) {}
const originalBody = $('WhatsApp Inbound').item.json.body;
const newBody = Object.assign({}, originalBody, { Body: '[صورة]: ' + (parsed.description || '') });
return [{ json: { body: newBody, isTravelDocument: !!parsed.is_travel_document }, binary: $input.item.binary }];

